        case status
    }

    public init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .status)
        switch tag {
        case "running": self = .running(try Running(from: decoder))
        case "done": self = .done(try Done(from: decoder))
        case "failed": self = .failed(try Failed(from: decoder))
        default: self = .unknown(tag)
