    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: TagKey.self)
        switch self {
        case .running(let value):
            try container.encode("running", forKey: .status)
            try value.encode(to: encoder)
        case .done(let value):
            try container.encode("done", forKey: .status)
            try value.encode(to: encoder)
        case .failed(let value):
            try container.encode("failed", forKey: .status)
            try value.encode(to: encoder)
        case .unknown(let tag):
            try container.encode(tag, forKey: .status)
        }
    }
}

