        switch tag {
        case "thread.event": self = .threadEvent(try ThreadEvent(from: decoder))
        case "message.created": self = .messageCreated(try MessageCreated(from: decoder))
        case "message.updated": self = .messageUpdated(try MessageUpdated(from: decoder))
        case "thread.updated": self = .threadUpdated(try ThreadUpdated(from: decoder))
        case "thread.removed": self = .threadRemoved(try ThreadRemoved(from: decoder))
        case "worktree.updated": self = .worktreeUpdated(try WorktreeUpdated(from: decoder))
        case "thread.pullRequests": self = .threadPullRequests(try ThreadPullRequests(from: decoder))
        case "pullRequest.guide": self = .pullRequestGuide(try PullRequestGuide(from: decoder))
        case "terminal.data": self = .terminalData(try TerminalData(from: decoder))
        case "terminal.exited": self = .terminalExited(try TerminalExited(from: decoder))
        default: self = .unknown(tag)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: TagKey.self)
        switch self {
        case .threadEvent(let value):
            try container.encode("thread.event", forKey: .type)
            try value.encode(to: encoder)
        case .messageCreated(let value):
            try container.encode("message.created", forKey: .type)
            try value.encode(to: encoder)
        case .messageUpdated(let value):
            try container.encode("message.updated", forKey: .type)
            try value.encode(to: encoder)
        case .threadUpdated(let value):
            try container.encode("thread.updated", forKey: .type)
            try value.encode(to: encoder)
        case .threadRemoved(let value):
            try container.encode("thread.removed", forKey: .type)
            try value.encode(to: encoder)
        case .worktreeUpdated(let value):
            try container.encode("worktree.updated", forKey: .type)
            try value.encode(to: encoder)
        case .threadPullRequests(let value):
            try container.encode("thread.pullRequests", forKey: .type)
            try value.encode(to: encoder)
        case .pullRequestGuide(let value):
            try container.encode("pullRequest.guide", forKey: .type)
            try value.encode(to: encoder)
        case .terminalData(let value):
            try container.encode("terminal.data", forKey: .type)
            try value.encode(to: encoder)
        case .terminalExited(let value):
            try container.encode("terminal.exited", forKey: .type)
